@@ -0,0 +1,60 @@
+/* Layout widgets (Home dashboards). Loaded after Bootstrap. */
+
+.calendar-grid {
+  display: grid;
+  grid-template-columns: repeat(7, minmax(0, 1fr));
+  gap: 1px;
+  background: #dee2e6;
+  border: 1px solid #dee2e6;
+  border-radius: 0.25rem;
+  overflow: hidden;
+}
+
+.calendar-weekday {
+  background: #f8f9fa;
+  padding: 0.35rem 0.4rem;
+  font-size: 0.75rem;
+  font-weight: 600;
+  text-align: center;
+  color: #6c757d;
+}
+
+.calendar-day {
+  background: #fff;
+  min-height: 5.5rem;
+  padding: 0.25rem 0.35rem;
+  display: flex;
+  flex-direction: column;
+  gap: 0.1rem;
+  align-items: stretch;
+}
+
+.calendar-day-outside {
+  background: #f8f9fa;
+  color: #adb5bd;
+}
+
+.calendar-day-num {
+  font-size: 0.75rem;
+  font-weight: 600;
+  margin-bottom: 0.15rem;
+}
+
+.calendar-item {
+  display: block;
+  width: 100%;
+  overflow: hidden;
+  text-overflow: ellipsis;
+  white-space: nowrap;
+  font-size: 0.7rem;
+  line-height: 1.2;
+  color: #0d6efd;
+}
+
+.calendar-item:hover {
+  text-decoration: underline !important;
+}
+
+.calendar-more {
+  font-size: 0.65rem;
+}
